import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()[:12]

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.1.4"})

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice headless mode"""
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    uploaded = request.files['file']
    if uploaded.filename == '':
        return jsonify({"error": "Empty filename"}), 400

    if not allowed_file(uploaded.filename):
        return jsonify({"error": "File type not allowed"}), 415

    output_format = request.form.get('format', 'pdf')
    # Validate output format
    if output_format not in ('pdf', 'html', 'txt'):
        return jsonify({"error": "Unsupported output format"}), 400

    job_id = generate_job_id(uploaded.filename)
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)

    safe_name = secure_filename(uploaded.filename)
    input_path = os.path.join(job_dir, safe_name)
    uploaded.save(input_path)

    # Additional page range parameter for partial conversion
    page_range = request.form.get('pages', '')

    # Build conversion command
    cmd = f"libreoffice --headless --convert-to {output_format}"

    if page_range:
        # Allow user to specify page range for conversion
        cmd += f" --outdir {job_dir} -env:UserInstallation=file:///tmp/.libreoffice_user {input_path}"
        # Apply page filter via macro
        macro_cmd = f"libreoffice --headless --invisible --norestore -env:UserInstallation=file:///tmp/.libreoffice_user 'macro:///Standard.Module1.ExportPages({input_path},{page_range})'"
        result = subprocess.run(macro_cmd, shell=True, capture_output=True, timeout=60, cwd=job_dir)
    else:
        cmd += f" --outdir {job_dir} {input_path}"
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=60, cwd=job_dir)

    if result.returncode != 0:
        return jsonify({"error": "Conversion failed", "details": result.stderr.decode()[:200]}), 500

    # Find output file
    output_name = safe_name.rsplit('.', 1)[0] + '.' + output_format
    output_path = os.path.join(job_dir, output_name)

    if not os.path.exists(output_path):
        return jsonify({"error": "Output file not generated"}), 500

    return send_file(output_path, as_attachment=True, download_name=output_name)

@app.route('/api/v1/batch', methods=['POST'])
def batch_convert():
    """Batch conversion endpoint - accepts JSON with file URLs"""
    data = request.get_json()
    if not data or 'urls' not in data:
        return jsonify({"error": "Missing urls field"}), 400

    results = []
    for url in data['urls'][:5]:  # Limit to 5 files
        # Download and convert
        fetch_cmd = f"curl -sL -o /tmp/batch_{generate_job_id(url)}.doc '{url}'"
        subprocess.run(fetch_cmd, shell=True, timeout=30)
        results.append({"url": url, "status": "queued"})

    return jsonify({"batch_id": generate_job_id(str(time.time())), "results": results})

@app.route('/api/v1/status/<job_id>', methods=['GET'])
def job_status(job_id):
    """Check conversion job status"""
    # Sanitize job_id to prevent path traversal
    if not job_id.isalnum():
        return jsonify({"error": "Invalid job ID"}), 400
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    if os.path.exists(job_dir):
        files = os.listdir(job_dir)
        return jsonify({"job_id": job_id, "files": files, "status": "complete"})
    return jsonify({"error": "Job not found"}), 404

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
